/// A version: a struct and a nested table among fixed fields, written whole
#[derive(Clone, Copy, Debug)]
pub struct Box<'a> {
    bytes: &'a [u8],
}

impl<'a> Box<'a> {
    /// The version of the format, which the header carries and [`Self::new`] checks
    pub const FORMAT_VERSION: u32 = 1;

    const LAYOUT: TableLayout<true> = TableLayout::DEFAULT.versioned();

    /// Reads a [`Box`] from `bytes`
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if `bytes` are in another format version.
    pub fn new(bytes: &'a [u8]) -> Result<Self, DecodeError> {
        let buffer = ByteBuffer::new(bytes, Self::LAYOUT);

        let version = buffer.version()?;
        if version != Self::FORMAT_VERSION {
            return Err(DecodeError::UnsupportedVersion {
                version,
                supported: Self::FORMAT_VERSION,
            });
        }

        Ok(Self { bytes })
    }

    /// Returns the format version in the header of `bytes`, without checking
    /// it, so that an application can choose the reader of that version
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the header doesn't fit in `bytes`.
    pub fn version_of(bytes: &[u8]) -> Result<u32, DecodeError> {
        ByteBuffer::new(bytes, Self::LAYOUT).version()
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn min(&self) -> Result<Vec2, DecodeError> {
        let buffer = ByteBuffer::new(self.bytes, Self::LAYOUT);
        let position = buffer.root_offset(0)?;
        let bytes = buffer.get_struct(position, Vec2::SIZE)?;

        Vec2::read(bytes)
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn max(&self) -> Result<Vec2, DecodeError> {
        let buffer = ByteBuffer::new(self.bytes, Self::LAYOUT);
        let position = buffer.root_offset(1)?;
        let bytes = buffer.get_struct(position, Vec2::SIZE)?;

        Vec2::read(bytes)
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn range(&self) -> Result<Range<'a>, DecodeError> {
        let buffer = ByteBuffer::new(self.bytes, Self::LAYOUT);
        let position = buffer.root_offset(2)?;
        Ok(Range::new(self.bytes, position))
    }
}

/// The fields of a [`Box`], to write
#[derive(Clone, Debug)]
pub struct BoxFields {
    pub min: Vec2,
    pub max: Vec2,
    pub range: RangeFields,
}

impl BoxFields {
    /// Writes a [`Box`] with every field
    ///
    /// # Errors
    ///
    /// Returns a [`BuildError`] if it's longer than its offset type, `uint32`, addresses.
    pub fn serialize(&self) -> Result<Vec<u8>, BuildError> {
        let mut sizer = TableSizer::versioned(3, Box::LAYOUT, Box::FORMAT_VERSION)?;
        sizer.add_struct(Vec2::SIZE);
        sizer.add_struct(Vec2::SIZE);
        sizer.add_table(RangeFields::ALIGNMENT);
        self.range.size(&mut sizer);

        let mut writer = sizer.writer()?;
        writer.set_struct(0, &self.min.to_bytes());
        writer.set_struct(1, &self.max.to_bytes());
        writer.set_table(2, RangeFields::ALIGNMENT);
        self.range.write(&mut writer);

        writer.into_bytes()
    }
}

